package com.example.bandlink.entity; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="notifications") public class Notification{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false) User user;@Column(nullable=false,length=30) String type;@Column(nullable=false,columnDefinition="text") String content;Long relatedId;@Column(nullable=false)LocalDateTime createdAt;LocalDateTime readAt;protected Notification(){}public Notification(User u,String t,String c,Long r,LocalDateTime n){user=u;type=t;content=c;relatedId=r;createdAt=n;}public Long getId(){return id;}public String getType(){return type;}public String getContent(){return content;}public Long getRelatedId(){return relatedId;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getReadAt(){return readAt;}public void markRead(LocalDateTime n){readAt=n;}}
